import{z as o,x as l,o as t,c as s,q as A,j as B,D as a,d as r,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"因子研究报告的规范","description":"","frontmatter":{"title":"因子研究报告的规范","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-reporting-standard.md","filePath":"quant/fz-reporting-standard.md","lastUpdated":1791063341000}'),p={name:"quant/fz-reporting-standard.md"};function d(h,E,u,C,m,D){const e=l("Mermaid");return t(),s("div",null,[E[2]||(E[2]=A('<h1 id="因子研究报告的规范" tabindex="-1">因子研究报告的规范 <a class="header-anchor" href="#因子研究报告的规范" aria-label="Permalink to &quot;因子研究报告的规范&quot;">​</a></h1><div class="epigraph"><p>因子研究到写进报告才算完成：报告是研究的接口，接口规范决定它能不能被复核、复用与推翻——省略的每一个参数，都是转嫁给下一个读者的成本。</p><footer>—— 据 Harvey, Liu &amp; Zhu, Review of Financial Studies, 2016；站内研究纪律课（预注册、台账、复盘）整理</footer></div><p><a href="/quant/fz-exposure-management">上一课</a>管住了账本里的暴露；本课管住纸面。前九课的每一环都产出文件：构造约定、控制集、拥挤分项、衰减估计、家族坐标、条件设定、边际贡献快照——最终要装进一份可复核的研究报告。<a href="/quant/hypothesis-preregistration">假设预注册</a>、<a href="/quant/research-log-discipline">研究台账</a>与<a href="/quant/research-postmortem">复盘</a>给了过程纪律；本课把因子研究报告的骨架与写作规则一次写死，作为全课程的汇总接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有规范的报告有四种共同死法。构造参数不全：换一个人或三个月后的作者，无法重出同一序列——构造课的自由度有一处没写，复现就断。只报好口径：全样本显著、子样本消失的因子只给你看全样本。不报试验次数：没有 N，「t=2.5」在试过五十个变体的背景下毫无意义——多重检验折价（<a href="/quant/harvey-liu-zhu">Harvey–Liu–Zhu</a>、<a href="/quant/multiple-testing-factors">多重检验下的因子</a>）需要 N 作为输入；报告不给 N，读者无法打折。把 t 当结论：统计显著但年化价差低于交易成本，t 再大也不构成可执行命题。四种死法指向同一件事：报告不是结论的容器，是证据链的接口。</p><h3 id="骨架七节" tabindex="-1">骨架七节 <a class="header-anchor" href="#骨架七节" aria-label="Permalink to &quot;骨架七节&quot;">​</a></h3><p><span class="marginnote">Harvey, Liu &amp; Zhu (2016, RFS) 在统计了发表因子群后建议：新因子的 t 统计量应过 3.0 而非 1.96——这不是抬高门槛的洁癖，是对「数百个候选里挑最大 t」这一选择效应的定价。报告写出 N，读者才能自己决定用哪个门槛打折。</span></p><p>一节，假设与理由：溢价从哪来（风险补偿还是行为），可证伪的判据是什么——判据在看过数据之前写下（预注册）。二节，数据：域、PIT 来源与版本、公司行动与退市处理。三节，构造：构造课的三层自由度全部显式，参数化到代码可直读。四节，主检验：全样本与分段子样本的 IC、分位数价差、多空收益（成本前后），t 与经济幅度并列。五节，稳健性：构造变体、子集、正交化到既有因子（控制集明示），试验次数 N 与折价口径。六节，组合含义：边际贡献快照、容量与拥挤状态、暴露含义。七节，判据与处置：进或不进账本的条件，以及失败的复盘链接。</p>',8)),(t(),B(n,null,{default:a(()=>[i(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%87%E8%AE%BE%E4%B8%8E%E5%8F%AF%E8%AF%81%E4%BC%AA%E5%88%A4%E6%8D%AE%EF%BC%88%E9%A2%84%E6%B3%A8%E5%86%8C%EF%BC%89%22%5D%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%EF%BC%9APIT%20%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20DATA%20--%3E%20CONS%5B%22%E6%9E%84%E9%80%A0%EF%BC%9A%E8%87%AA%E7%94%B1%E5%BA%A6%E5%85%A8%E9%83%A8%E6%98%BE%E5%BC%8F%22%5D%0A%20%20CONS%20--%3E%20MAIN%5B%22%E4%B8%BB%E6%A3%80%E9%AA%8C%EF%BC%9At%20%E4%B8%8E%E7%BB%8F%E6%B5%8E%E5%B9%85%E5%BA%A6%E5%B9%B6%E5%88%97%22%5D%0A%20%20MAIN%20--%3E%20ROB%5B%22%E7%A8%B3%E5%81%A5%E6%80%A7%20%2B%20%E8%AF%95%E9%AA%8C%E6%AC%A1%E6%95%B0%20N%22%5D%0A%20%20ROB%20--%3E%20PORT%5B%22%E7%BB%84%E5%90%88%E5%90%AB%E4%B9%89%EF%BC%9A%E8%BE%B9%E9%99%85%E8%B4%A1%E7%8C%AE%2F%E5%AE%B9%E9%87%8F%2F%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20PORT%20--%3E%20VERD%5B%22%E5%88%A4%E6%8D%AE%E4%B8%8E%E5%A4%84%E7%BD%AE%22%5D%0A%20%20VERD%20--%3E%20ARCH%5B%22%E5%BD%92%E6%A1%A3%EF%BC%9A%E4%BB%A3%E7%A0%81%2B%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%E5%8F%AF%E9%87%8D%E7%BB%98%E6%AF%8F%E5%BC%A0%E5%9B%BE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写作规则高于模板。</p><p><span class="marginnote">「数字带区间」的数字实例：半衰期写「\\(\\tau\\) 在 2 到 5 年之间」而非「\\(\\tau=3.2\\) 年」。前者告诉你：按最坏情形（2 年）安排退出也来得及；后者只是给幻灯片用的一个好看小数。决策要的是「最坏情形下结论还站不站得住」，所以区间是给决策的，点估计是给演讲的。</span>其一，负结果同模板：不显著的因子按同一骨架归档，失败清单可检索才不重复付学费。其二，数字带区间：半衰期、残差 IR、容量都给区间不给点估计；点估计是给幻灯片的，区间是给决策的。其三，每个数字可重绘：报告附代码与数据快照，任何一张图能重出——这是「可复核」的操作性定义。其四，pitch 与报告分离：对外材料可以说故事，内部报告只认证据链；两者混写的研究部门，迟早用自己的故事定价。其五，报告有版本：状态变化以修订而非覆写记录，历史判断不回改。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么规范是统计要求而不只是文风？多重检验折价的机制链条是：试了 N 个候选，挑最大的 t，其零分布是「N 次取最大」的极值分布——家族错误率由 N 决定。</p><p><span class="marginnote">数字实例：只试 1 个候选时，\\(t=1.96\\) 对应 5% 假阳性；但若试了 100 个纯噪声变体、专挑最大的 t 报告，「最大 t 不超过 1.96」的概率只剩约 \\(0.975^{100}\\approx 8\\%\\)——也就是说九成以上的概率你会看到一个大得吓人的假 t。门槛必须随 N 抬，这正是「报告写 N」在统计上的含义。</span></p>',6)),(t(),B(n,null,{default:a(()=>[i(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%95%201%20%E4%B8%AA%E5%80%99%E9%80%89%22%5D%20--%3E%20AZ%5B%22%E9%9B%B6%E5%88%86%E5%B8%83%EF%BC%9A%E6%99%AE%E9%80%9A%20t%20%E5%88%86%E5%B8%83%22%5D%0A%20%20B%5B%22%E8%AF%95%20N%20%E4%B8%AA%E5%80%99%E9%80%89%EF%BC%8C%E5%8F%AA%E6%8A%A5%E6%9C%80%E5%A4%A7%20t%22%5D%20--%3E%20BZ%5B%22%E9%9B%B6%E5%88%86%E5%B8%83%EF%BC%9AN%20%E6%AC%A1%E5%8F%96%E6%9C%80%E5%A4%A7%E7%9A%84%E6%9E%81%E5%80%BC%E5%88%86%E5%B8%83%22%5D%0A%20%20AZ%20--%3E%20C%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20t%20%E5%80%BC%EF%BC%8C%E5%90%AB%E4%B9%89%E5%AE%8C%E5%85%A8%E4%B8%8D%E5%90%8C%22%5D%0A%20%20BZ%20--%3E%20C%0A%20%20C%20--%3E%20D%5B%22%E9%9A%90%E5%8E%BB%20N%20%3D%20%E9%9A%90%E5%8E%BB%E9%9B%B6%E5%81%87%E8%AE%BE%EF%BC%9At%20%E4%B8%8D%E5%8F%AF%E8%A7%A3%E9%87%8A%22%5D%0A%20%20D%20--%3E%20R%5B%22%E6%8A%A5%E5%91%8A%E5%86%99%20N%EF%BC%8C%E8%AF%BB%E8%80%85%E6%89%8D%E8%83%BD%E8%87%AA%E8%A1%8C%E6%89%93%E6%8A%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p>报告隐去 N，等于隐去了自己结论的零假设；这不是不严谨，是统计上不可解释。复现机制同理：构造参数不全是把经验命题变成不可证伪的口号——「因子有效」若无法被别人重出，就退化为信任问题。规范的每一条都对应一个已知的失败机制：模板不是仪式，是失败模式的清单化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规范不保证正确：七节写满也可能结论错误，规范保证的是错误可被发现。</p><p><span class="marginnote">为什么重要：规范像建筑验收标准——验收合格不保证楼永远不塌，但保证裂缝有记录、管线可查、谁改过图纸有签名。没有规范的研究结论错了，你连「错在哪一步」都无从查起；有规范的结论错了，扰动表与判据会直接指到出问题的那节。可发现性，是证据链对错误的全部主张。</span>报告不含仓位建议之外的投资故事，也不承担合规审查——对外发布的合规是另一道流程。会议纪要与委员会决议不属于研究报告，不要混进证据链。规范的粒度按团队规模定：一个人的团队可以把七节压成一页加一个 notebook，但 N、控制集、判据不能省——那是统计上不可协商的部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报告是证据链接口：构造、N、控制集、判据缺一不可，其余可按团队压缩。</li><li>多重检验折价的计算需要 N；隐去 N 等于隐去零假设。</li><li>t 与经济幅度并列，成本后的可执行性是入场券不是附录。</li><li>负结果同模板归档，报告带版本，每个数字可从快照重绘。</li><li>pitch 与内部报告分离，故事不进证据链。</li><li>出处：Harvey, Liu &amp; Zhu, <em>RFS</em>, 2016；过程纪律见站内预注册、台账与复盘课。</li></ul>',6))])}const c=o(p,[["render",d]]);export{F as __pageData,c as default};
